import { v4 as uuidv4 } from 'uuid';

const TaskStore = {
  tasks: [],

  getTasks(filter) {
    let tasks = [...this.tasks];
    if (filter === 'active') {
      tasks = tasks.filter(task => !task.completed);
    } else if (filter === 'completed') {
      tasks = tasks.filter(task => task.completed);
    }
    return tasks;
  },

  addTask(title) {
    if (!title || title.trim() === '') return;
    const newTask = {
      id: uuidv4(),
      title: title.trim(),
      completed: false,
      createdAt: new Date().toISOString()
    };
    this.tasks = [newTask, ...this.tasks];
    this.saveToLocalStorage();
    return newTask;
  },

  toggleTaskCompletion(taskId) {
    this.tasks = this.tasks.map(task =>
      task.id === taskId ? { ...task, completed: !task.completed } : task
    );
    this.saveToLocalStorage();
  },

  editTask(taskId, newTitle) {
    if (!newTitle || newTitle.trim() === '') return;
    this.tasks = this.tasks.map(task =>
      task.id === taskId ? { ...task, title: newTitle.trim() } : task
    );
    this.saveToLocalStorage();
  },

  deleteTask(taskId) {
    this.tasks = this.tasks.filter(task => task.id !== taskId);
    this.saveToLocalStorage();
  },

  saveToLocalStorage() {
    try {
      const data = JSON.stringify(this.tasks);
      localStorage.setItem('tasks', data);
    } catch (error) {
      console.error('localStorage save error:', error);
    }
  },

  loadFromLocalStorage() {
    try {
      const data = localStorage.getItem('tasks');
      if (data) {
        this.tasks = JSON.parse(data);
      }
    } catch (error) {
      console.error('localStorage load error:', error);
      this.tasks = [];
    }
  },

  clearCompleted() {
    this.tasks = this.tasks.filter(task => !task.completed);
    this.saveToLocalStorage();
  }
};

TaskStore.loadFromLocalStorage();
export default TaskStore;

import React, { useState } from 'react';
import TaskStore from '../TaskStore';

const TaskItem = ({ task }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(task.title);

  const handleToggle = () => {
    TaskStore.toggleTaskCompletion(task.id);
    setIsEditing(false);
  };

  const handleDelete = () => {
    TaskStore.deleteTask(task.id);
  };

  const handleSave = () => {
    TaskStore.editTask(task.id, editTitle);
    setIsEditing(false);
    setEditTitle(task.title);
  };

  const handleInputChange = (e) => {
    setEditTitle(e.target.value);
  };

  return (
    <li
      style={{ textDecoration: task.completed ? 'line-through' : 'none', marginBottom: '8px' }}
    >
      {isEditing ? (
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <input
            type="text"
            value={editTitle}
            onChange={handleInputChange}
            style={{ flex: 1, padding: '4px', fontSize: '14px' }}
          />
          <button
            onClick={handleSave}
            style={{ padding: '4px 8px', marginLeft: '8px', background: '#3b82f6', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
            disabled={editTitle.trim() === '' || editTitle === task.title}
          >
            Save
          </button>
        </div>
      ) : (
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <input
            type="checkbox"
            checked={task.completed}
            onChange={handleToggle}
            style={{ marginRight: '8px', transform: 'scale(1.2)' }}
          />
          <span style={{ flex: 1, fontSize: '14px' }> {task.title} </span>
          <button
            onClick={handleDelete}
            style={{ padding: '4px 8px', marginLeft: '8px', background: '#ef4444', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
            aria-label="Delete task"
          >
            Delete
          </button>
        </div>
      )}
    </li>
  );
};

export default TaskItem;

import React, { useState } from 'react';
import TaskStore from '../TaskStore';

const TaskInput = () => {
  const [inputValue, setInputValue] = useState('');

  const handleAddTask = (e) => {
    e.preventDefault();
    if (!inputValue.trim()) return;
    TaskStore.addTask(inputValue);
    setInputValue('');
  };

  return (
    <form style={{ marginBottom: '16px' }} onSubmit={handleAddTask}>
      <input
        type="text"
        placeholder="Add a new task..."
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        style={{ padding: '8px', fontSize: '14px', width: '300px', border: '1px solid #d1d5db', borderRadius: '4px' }}
        required
      />
      <button
type="submit"
        style={{ padding: '8px 16px', marginLeft: '8px', background: '#10b981', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '14px' }}
        disabled={!inputValue.trim()}
      >
        Add
      </button>
    </form>
  );
};

export default TaskInput;

import React from 'react';
import TaskStore from '../TaskStore';

const TaskFilters = () => {
  const [filter, setFilter] = useState('all');

  const handleFilterChange = (e) => {
    setFilter(e.target.value);
  };

  return (
    <div style={{ marginBottom: '16px', justifyContent: 'space-between' }}>
      <label
        style={{ marginRight: '16px', fontSize: '14px', cursor: 'pointer' }}
        >
          <input
            type="radio"
            name="filter"
            value="all"
            onChange={handleFilterChange}
            checked={filter === 'all'}
          />
          All
        </label>
      <label
        style={{ marginRight: '16px', fontSize: '14px', cursor: 'pointer' }}
        >
          <input
            type="radio"
            name="filter"
            value="active"
            onChange={handleFilterChange}
            checked={filter === 'active'}
          />
          Active
        </label>
      <label
        style={{ fontSize: '14px', cursor: 'pointer' }}
        >
          <input
            type="radio"
            name="filter"
            value="completed"
            onChange={handleFilterChange}
            checked={filter === 'completed'}
          />
          Completed
        </label>
    </div>
  );
};

export default TaskFilters;

