import TaskStore from '../TaskStore';

describe('TaskStore', () => {
  beforeEach(() => {
    localStorage.clear();
    TaskStore.tasks = [];
  });

  describe('addTask', () => {
    it('should add a task with a title', () => {
      const task = TaskStore.addTask('Test task');
      expect(TaskStore.tasks.length).toBe(1);
      expect(task.title).toBe('Test task');
      expect(task.completed).toBe(false);
    });

    it('should not add empty task', () => {
      TaskStore.addTask('');
      expect(TaskStore.tasks.length).toBe(0);
    });
  });

  describe('toggleTaskCompletion', () => {
    it('should mark task as completed', () => {
      TaskStore.addTask('Test task');
      TaskStore.toggleTaskCompletion(TaskStore.tasks[0].id);
      expect(TaskStore.tasks[0].completed).toBe(true);
    });

    it('should mark task as uncompleted', () => {
      TaskStore.addTask('Test task');
      TaskStore.toggleTaskCompletion(TaskStore.tasks[0].id);
      TaskStore.toggleTaskCompletion(TaskStore.tasks[0].id);
      expect(TaskStore.tasks[0].completed).toBe(false);
    });
  });

  describe('editTask', () => {
    it('should edit task title', () => {
      TaskStore.addTask('Original task');
      TaskStore.editTask(TaskStore.tasks[0].id, 'Edited task');
      expect(TaskStore.tasks[0].title).toBe('Edited task');
    });

    it('should not edit with empty title', () => {
      TaskStore.addTask('Original task');
      TaskStore.editTask(TaskStore.tasks[0].id, '');
      expect(TaskStore.tasks[0].title).toBe('Original task');
    });
  });

  describe('deleteTask', () => {
    it('should delete a task', () => {
      TaskStore.addTask('Task to delete');
      TaskStore.deleteTask(TaskStore.tasks[0].id);
      expect(TaskStore.tasks.length).toBe(0);
    });
  });

  describe('filterTasks', () => {
    it('should filter all tasks', () => {
      TaskStore.addTask('Task 1');
      TaskStore.addTask('Task 2');
      TaskStore.tasks[1].completed = true;
      const allTasks = TaskStore.getTasks('all');
      expect(allTasks.length).toBe(2);
    });

    it('should filter active tasks', () => {
      TaskStore.addTask('Task 1');
      TaskStore.addTask('Task 2');
      TaskStore.tasks[1].completed = true;
      const activeTasks = TaskStore.getTasks('active');
      expect(activeTasks.length).toBe(1);
    });

    it('should filter completed tasks', () => {
      TaskStore.addTask('Task 1');
      TaskStore.addTask('Task 2');
      TaskStore.tasks[1].completed = true;
      const completedTasks = TaskStore.getTasks('completed');
      expect(completedTasks.length).toBe(1);
    });
  });
});

import React from 'react';
import { render, fireEvent } from '@testing-library/react';
