    const activeRadio = getByLabelText('Active');
    fireEvent.click(activeRadio);
  });

  it('should filter completed tasks', () => {
    const { getByLabelText } = render(<TaskFilters />);
    const completedRadio = getByLabelText('Completed');
    fireEvent.click(completedRadio);
  });
});

import React from 'react';
import { render, fireEvent } from '@testing-library/react';
import TaskInput from '../TaskInput';
import TaskStore from '../../TaskStore';

describe('TaskInput', () => {
  beforeEach(() => {
    localStorage.clear();
    TaskStore.tasks = [];
  });

  it('should add a task', () => {
    const { getByPlaceholderText } = render(<TaskInput />);
    const input = getByPlaceholderText('Add a new task...');
    fireEvent.change(input, { target: { value: 'New task' } });
    fireEvent.click(getByText('Add'));
    expect(TaskStore.tasks.length).toBe(1);
    expect(TaskStore.tasks[0].title).toBe('New task');
  });

  it('should not add empty task', () => {
    const { getByPlaceholderText } = render(<TaskInput />);
    const input = getByPlaceholderText('Add a new task...');
    fireEvent.change(input, { target: { value: '' } });
    fireEvent.click(getByText('Add'));
    expect(TaskStore.tasks.length).toBe(0);
  });
});
